    types::Package* rec::doPkg(reader* r)
    {
        auto path = rec::String(gocpp::recv(r));
        //Go switch emulation
        {
            auto condition = path;
            int conditionId = -1;
            if(condition == ""_s) { conditionId = 0; }
            else if(condition == "builtin"_s) { conditionId = 1; }
            else if(condition == "unsafe"_s) { conditionId = 2; }
            switch(conditionId)
            {
                case 0:
                    path = rec::PkgPath(gocpp::recv(r->p));
                    break;
                // universe
                case 1:
                    return nullptr;
                    break;
                case 2:
                    return types::Unsafe;
                    break;
            }
        }

        if(auto pkg = r->p->imports[path]; pkg != nullptr)
        {
            return pkg;
        }

        auto name = rec::String(gocpp::recv(r));

        auto pkg = types::NewPackage(path, name);
        r->p->imports[path] = pkg;

        return pkg;
    }

